/// Iterate the whole bank (tests + tooling sync checks).
pub fn bank() -> &'static [(&'static str, &'static str, OracleMatrix)] {
    BANK
}

/// Look up a frozen specimen. Returns `None` for payloads not in the
/// bank — add those via the generator (see module docs).
pub fn oracle_matrix(symbology: &str, text: &str) -> Option<OracleMatrix> {
    BANK.iter()
        .find(|(s, t, _)| *s == symbology && *t == text)
        .map(|(_, _, m)| *m)
}
